// Input starts a cached, decorative loop before the paid request resolves.
// A response is still verified by game.js before any winning board is shown.
let pendingInput = null;
let warmedInput = null;
function inputKey(root) {
  return [...root.children].map(c => [...c.children].filter(t => t._tile)
    .map(t => `${t._tile.symbol}:${+!!t._tile.enhanced}`).join(',')).join('/');
}
function makeInput(root) {
  const originals = [...root.children];
  if (originals.length !== 5) throw Error('Expected visible input reels');
  const dpr = Math.min(1.5, window.devicePixelRatio || 1);
  const cols = originals.map((original, i) => {
    const tiles = [...original.children].filter(t => t._tile);
    const box = original.getBoundingClientRect();
    const gap = parseFloat(getComputedStyle(original).rowGap) || 0;
    const pitch = (box.height + gap) / tiles.length;
    const period = pitch * tiles.length;
    if (box.width < 1 || period < 1) throw Error('Input viewport unavailable');
    const canvas = document.createElement('canvas');
    canvas.className = 'reel-strip reel-canvas input-canvas';
    canvas.setAttribute('aria-hidden', 'true');
    canvas.width = Math.ceil(box.width * dpr);
    canvas.height = Math.ceil(period * 2 * dpr);
    Object.assign(canvas.style, {width:`${box.width}px`,height:`${period * 2}px`});
    const ctx = canvas.getContext('2d', {alpha:true});
    if (!ctx) throw Error('Input canvas unavailable');
    ctx.setTransform(canvas.width / box.width, 0, 0, canvas.height / (period * 2), 0, 0);
    for (let copy=0;copy<2;copy++) tiles.forEach((tile, row) => {
      const im = tile.querySelector('.tile-image');
      if (!im?.complete || !im.naturalWidth) throw Error('Input tile not decoded');
      ctx.drawImage(im, 0, copy * period + row * pitch, box.width, pitch - gap);
    });
    const surface = document.createElement('div');
    surface.className = 'reel-surface';
    surface.setAttribute('aria-hidden', 'true');
    surface.append(canvas);
    return {original,canvas,surface,i,period,w:box.width,h:box.height,animation:null,started:false,transferred:false};
  });
  return {root,key:inputKey(root),width:root.clientWidth,height:root.clientHeight,cols};
}
function prewarm(root) {
  if (pendingInput || active || !root?.children.length) return;
  try {
    const key = inputKey(root);
    if (warmedInput?.key === key && warmedInput.width === root.clientWidth && warmedInput.height === root.clientHeight) return;
    warmedInput = makeInput(root);
  } catch (_) { warmedInput = null; }
}
function abortInput() {
  const input = pendingInput;
  if (!input) return;
  input.disposed = true;
  for (const timer of input.timers) clearTimeout(timer);
  cancelAnimationFrame(input.frame);
  for (const c of input.cols) {
    try { c.animation?.cancel(); } catch (_) {}
    c.surface.remove();
    c.canvas.width = c.canvas.height = 1;
  }
  pendingInput = null;
  if (!active) document.documentElement.classList.remove('reels-running');
}
function beginInput({root, turbo=false, shouldSkip=()=>false}) {
  if (pendingInput || active || shouldSkip() || document.hidden) return;
  const inputAt = now();
  try {
    const key=inputKey(root);
    const warmed=warmedInput;
    const data=warmed && warmed.key===key && warmed.width===root.clientWidth && warmed.height===root.clientHeight
      ? warmed : makeInput(root);
    warmedInput=null;
    const input=pendingInput={...data,inputAt,starts:[],timers:[],frame:0,firstFrameMs:null,disposed:false};
    const cycle=turbo?360:520,stagger=turbo?45:85;
    const start=c=>{
      if(input.disposed||c.transferred||shouldSkip()||document.hidden)return;
      const from=`translate3d(0,${-c.period}px,0)`;
      c.canvas.style.transform=from;
      c.original.append(c.surface);
      c.animation=c.canvas.animate([{transform:from},{transform:'translate3d(0,0px,0)'}],
        {duration:cycle,iterations:Infinity,easing:'linear',fill:'both'});
      c.animation.playbackRate=.14;
      c.started=true;c.startAt=now();c.cycle=cycle;
      input.starts.push(c.i+1);signal('start',c.i+1);
    };
    document.documentElement.classList.add('reels-running');
    start(input.cols[0]);
    input.cols.slice(1).forEach(c=>input.timers.push(setTimeout(()=>start(c),stagger*c.i)));
    const sample=t=>{
      if(input.disposed)return;
      if(shouldSkip()||document.hidden){abortInput();return;}
      for(const c of input.cols){
        if(!c.started||c.transferred)continue;
        const elapsed=t-c.startAt;
        if(elapsed<280){const v=.14+.86*Math.min(1,Math.max(0,elapsed)/220);
          if(c.animation.updatePlaybackRate)c.animation.updatePlaybackRate(v);else c.animation.playbackRate=v;
        }
