  if(!prior?.started || prior.transferred || input.disposed)return false;
  // Freeze the source at the exact compositor phase before copying its view.
  const phase=((Number(prior.animation.currentTime)||0)%prior.cycle)/prior.cycle;
  const y=prior.period*(1-phase);
  const sy=prior.canvas.height/(2*prior.period);
  context.drawImage(prior.canvas,0,y*sy,prior.canvas.width,h*sy,0,distance,w,h);
  prior.transferred=true;
  prior.animation.cancel();prior.surface.remove();
  prior.canvas.width=prior.canvas.height=1;
  if(input.cols.every(x=>x.transferred)){
    input.disposed=true;cancelAnimationFrame(input.frame);input.timers.forEach(clearTimeout);
    if(pendingInput===input)pendingInput=null;
  }
  return true;
}

